const recordDraft=new RecordDraftQueue({
 save:(workspaceId,page)=>api('save',{workspaceId,page}),
 onSaved:saved=>{mergeSavedMetadata(recordDraft.page,saved);refreshComputed();const i=state.pages.findIndex(p=>p.id===saved.id);if(i>=0)state.pages[i]=saved;},
 onChange:()=>{if(recordDraft.page){const key=recordRecoveryKey(recordDraft.workspaceId,recordDraft.childId);try{recordDraft.dirty?localStorage.setItem(key,JSON.stringify(recordDraft.page)):localStorage.removeItem(key);}catch{}}renderSaveState();if(recordDraft.dirty)autoSyncUI?.edit();}
});
