function rawRecordContext(){if(!state.recordPeek||state.recordPeek.childId)return null;const owner=peekOwner(),row=owner?.database?.rows.find(r=>r.id===state.recordPeek.rowId);return row?{owner,row}:null;}
function currentBlockPage(){const raw=rawRecordContext();return raw?recordBlocks.page(raw.owner,raw.row):state.page;}
