 wait:()=>autoSyncUI?.network||Promise.resolve(),flush,checkpoint:()=>request('commit',{message:'批量移除记录前保存数据库'}),apply:result=>applyDatabaseChange(db=>Object.assign(db,result.page.database)),render,showPopover:propertyPopover,reposition:positionPropertyPopover,closeModal,toast,
 saveCSV:(name,csv)=>saveFile(name,encodeBase64(new TextEncoder().encode(csv)))
