const button=(label,action,kind='plain',glyph='',extra='')=>`<button class="button ${kind}" ${action?`data-action="${action}"`:''} ${extra.includes('type=')?'':'type="button"'} ${extra}>${glyph?icon(glyph):''}<span>${e(label)}</span></button>`;
const iconButton=(label,action,glyph,extra='')=>{const className=extra.match(/class="([^"\n]+)"/)?.[1]||'';return `<button class="icon-button ${className}" type="button" aria-label="${e(label)}" title="${e(label)}" data-action="${action}" ${extra.replace(/class="[^"\n]+"/,'')}>${icon(glyph)}</button>`;};
