function applyPreferences(){setLocale(state.config.preferences.language);if(desktopSupported&&lastDesktopLocale!==state.config.preferences.language){lastDesktopLocale=state.config.preferences.language;setDesktopLocale(lastDesktopLocale).catch(error=>{lastDesktopLocale='';toast(errorMessage(error),true);});}const theme=state.config.preferences.theme;document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;document.documentElement.dataset.font=state.config.preferences.font;}
