let renderedScope='';
function captureScroll(){const side=$('.sidebar-scroll'),main=$('.main-scroll'),top=side?.getBoundingClientRect().top;return {sidebar:side?.scrollTop||0,anchors:side?[...side.querySelectorAll('[data-page-id]')].filter(el=>el.getBoundingClientRect().bottom>top&&el.getBoundingClientRect().top<side.getBoundingClientRect().bottom).slice(0,3).map(el=>({id:el.dataset.pageId,offset:el.getBoundingClientRect().top-top})):[],main:main?.scrollTop||0,table:$('.database-table-wrap')?.scrollLeft||0,peek:$('.record-peek-scroll')?.scrollTop||0,graphLeft:$('.graph-canvas')?.scrollLeft||0,graphTop:$('.graph-canvas')?.scrollTop||0};}
function restoreScroll(position,sameScope){const side=$('.sidebar-scroll');if(side){side.scrollTop=position.sidebar;for(const anchor of position.anchors){const node=side.querySelector(`[data-page-id="${anchor.id}"]`);if(node){side.scrollTop+=node.getBoundingClientRect().top-side.getBoundingClientRect().top-anchor.offset;break;}}}if(sameScope){const main=$('.main-scroll');if(main){const behavior=main.style.scrollBehavior;main.style.scrollBehavior='auto';main.scrollTop=position.main;main.style.scrollBehavior=behavior;}if($('.database-table-wrap'))$('.database-table-wrap').scrollLeft=position.table;if($('.record-peek-scroll'))$('.record-peek-scroll').scrollTop=position.peek;const graph=$('.graph-canvas');if(graph){graph.scrollLeft=position.graphLeft;graph.scrollTop=position.graphTop;}}}
function render(){const scrollPosition=captureScroll(),scope=state.config?.activeId+':'+(state.recordPeek?.ownerId||state.route),sameScope=scope===renderedScope;editor.menu.close();editor.clearDrag();closeContextMenu();for(const url of assetURLs)URL.revokeObjectURL(url);assetURLs.clear();const focus=document.activeElement?.id,position=document.activeElement?.selectionStart;$('#app').innerHTML=`<div class="app-shell ${state.sidebarCollapsed?'sidebar-collapsed':''}">${sidebar()}<main>${header()}${pageTabsHTML()}<div class="main-scroll">${state.route==='home'?home():state.route==='trash'?trashPage():state.route==='graph'?graphHTML(graphCache.get(state.config.activeId,state.pages),graphState):state.recordPeek?peekBackground():documentPage()}</div>${state.recordPeek?recordPeekHTML():''}</main></div>`;bindInputs();hydrateAssets();if(focus&&$('#'+focus)){const el=$('#'+focus);el.focus({preventScroll:true});if(position!=null&&el.setSelectionRange)el.setSelectionRange(position,position);}resizeAll();restoreScroll(scrollPosition,sameScope);renderedScope=scope;editor.afterRender();databaseBatchUI.afterRender();}
