 const position=captureScroll(),next=document.createElement('div'),focus=document.activeElement?.id;next.innerHTML=databaseHTML();
 for(const node of [...region.children])if(node!==toolbar)node.remove();for(const node of [...next.children])if(!node.classList.contains('database-toolbar'))region.append(node);
