function renderSaveState(){const el=$('#save-state');if(el){const failed=state.saveError||recordDraft.error;const retry=$('.topbar [data-action="retry"]');if(failed&&!retry)el.insertAdjacentHTML('afterend',button(t('retry'),'retry','plain','restore'));if(!failed&&retry)retry.remove();el.classList.toggle('failed',!!(state.saveError||recordDraft.error));el.innerHTML=(state.saveError||recordDraft.error)?`${icon('info',14)}${t('saveError')}`:(state.saving||recordDraft.saving)?`${icon('clock',14)}${t('saving')}`:`<span class="status-dot"></span>${t('saved')}`;}}
function resize(el){el.style.height='auto';el.style.height=el.scrollHeight+'px';}
function resizeAll(){document.querySelectorAll('textarea').forEach(resize);}
function snapshot(){if(state.page){state.undo.push(clone(state.page));if(state.undo.length>60)state.undo.shift();state.redo=[];}}
function changed(){const raw=rawRecordContext();if(raw)recordBlocks.commit(raw.owner,raw.row);state.dirty=true;state.editSeq++;state.saveError='';try{localStorage.setItem(recoveryKey(),JSON.stringify(state.page));}catch{}clearTimeout(saveTimer);if(!autoSyncUI?.draftBlocked)saveTimer=setTimeout(()=>flush().catch(error=>toast(errorMessage(error),true)),600);autoSyncUI?.edit();renderSaveState();}
let flushPromise=null;
function flush(){clearTimeout(saveTimer);if(autoSyncUI?.network)return autoSyncUI.network.then(()=>flush());if(autoSyncUI?.draftBlocked)return Promise.reject(new Error(t('autoSyncDraftNeedsChoice')));if(flushPromise)return flushPromise;flushPromise=flushChanges().finally(()=>{flushPromise=null;});return flushPromise;}
async function flushChanges(){while(state.dirty||recordDraft.dirty){await recordDraft.flush();if(!state.dirty||!state.page){if(recordDraft.dirty)continue;return;}const p=clone(state.page),seq=state.editSeq,work=state.config.activeId,key=recoveryKey();state.saving=api('save',{workspaceId:work,page:p});renderSaveState();try{const saved=await state.saving;if(state.page?.id===saved.id&&state.config.activeId===work){mergeSavedMetadata(state.page,saved);refreshComputed();}const i=state.pages.findIndex(p=>p.id===saved.id);if(i>=0)state.pages[i]=saved;else state.pages.push(saved);state.dirty=state.editSeq!==seq;if(!state.dirty){localStorage.removeItem(key);}else{try{localStorage.setItem(key,JSON.stringify(state.page));}catch{}}state.saveError='';}catch(error){state.saveError=errorMessage(error);throw error;}finally{state.saving=null;renderSaveState();}}}
function resetWorkspaceView(){graphState=newGraphState();graphCache.clear();freeformState={page:'',selected:'',selectedIds:[]};pendingFreeform=null;const address=new URL(location.href);if(address.searchParams.has('workspace')||address.searchParams.has('page')){address.searchParams.set('workspace',state.config.activeId);address.searchParams.delete('page');window.history.replaceState(null,'',address.href);}state.sidebar=false;recordDraft.clear();state.page=null;state.pages=[];state.stats=null;state.status=null;state.dirty=false;state.recordPeek=null;state.openTabs=[];state.route='home';state.query='';state.dbQuery='';state.dbViewId='';state.view='table';state.dbSort='';state.dbDesc=false;state.dbGroup='';state.dbDate='';state.undo=[];state.redo=[];state.selectedPages.clear();state.trashSelected.clear();state.purgePlan=null;state.selectingPages=false;state.selectionWorkspace=state.config.activeId;}
async function refresh(){const [pages,stats,status]=await Promise.all([request('pages'),request('stats'),request('status')]);if(state.selectionWorkspace!==state.config.activeId){state.selectedPages.clear();state.trashSelected.clear();state.purgePlan=null;state.selectingPages=false;state.selectionWorkspace=state.config.activeId;}state.pages=pages;state.selectedPages=new Set([...state.selectedPages].filter(id=>pages.some(p=>p.id===id&&!p.deleted)));state.trashSelected=new Set([...state.trashSelected].filter(id=>pages.some(p=>p.id===id&&p.deleted)));state.stats=stats;state.status=status;}
async function navigate(route,{peek=null,preserveDatabase=false}={}){if(autoSyncUI?.network)await autoSyncUI.network;if(state.busy){toast(t('operationBusy'));return;}rememberDatabaseSession();state.busy=true;closeContextMenu();closeModal();render();try{await flush();recordDraft.clear();state.recordPeek=peek;state.route=route;if(freeformState.page!==route)freeformState={page:route,selected:'',selectedIds:[]};state.sidebar=false;state.query='';state.preview=false;state.undo=[];state.redo=[];if(!peek&&!preserveDatabase){state.dbQuery='';state.dbSort='';state.dbGroup='';state.dbDate='';}state.saveError='';state.page=state.pages.find(p=>p.id===route&&!p.deleted)?clone(state.pages.find(p=>p.id===route)):null;if(state.page?.database||!peek)restoreDatabaseSession(state.page);render();if(state.page){const key=recoveryKey();try{const draft=JSON.parse(localStorage.getItem(key)||'null');if(draft){if(draft.revision===state.page.revision){state.page=draft;changed();toast(t('saving'));}else{toast(t('unsavedWarning'),true);await request('save',{page:{...draft,id:'',revision:0,title:draft.title+' · 恢复副本',parentId:''}});localStorage.removeItem(key);await refresh();}}}catch(error){toast(errorMessage(error),true);}await recoverRecordDraft();}}finally{state.busy=false;render();if(!peek&&!preserveDatabase)$('.main-scroll')?.scrollTo(0,0);else $('.record-peek-scroll')?.scrollTo(0,0);}}
