async function acceptSyncResult(result){
 autoSyncUI?.acceptManual(result);
 await refresh();recordDraft.clear();state.recordPeek=null;state.undo=[];state.redo=[];
 if(state.page){state.page=clone(state.pages.find(p=>p.id===state.page.id&&!p.deleted));if(!state.page)state.route='home';}
 if(result.status==='conflict'){toast(t('syncNeedChoose'),true);showSyncConflict(result);return false;}
 toast(result.message);return true;
}
function showSyncConflict(plan){
 const workspaceId=state.config.activeId;modal(t('syncConflictTitle'),syncConflictHTML(plan),true);
 const form=$('#sync-conflict-form'),error=form.querySelector('.sync-operation-error');
 const update=()=>{const strategy=form.elements.strategy.value;form.querySelectorAll('[data-conflict-path]').forEach(input=>{input.disabled=strategy!=='merge';input.required=strategy==='merge';});form.querySelector('.sync-conflicts').hidden=strategy!=='merge';};
 form.querySelectorAll('[name=strategy]').forEach(input=>input.onchange=update);update();
 form.onsubmit=async event=>{event.preventDefault();if(state.busy)return;error.hidden=true;const strategy=form.elements.strategy.value,choices=Object.fromEntries([...form.querySelectorAll('[data-conflict-path]')].map(input=>[input.dataset.conflictPath,input.value]));
  state.busy=true;form.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);render();
  try{if(workspaceId!==state.config.activeId)throw new Error(t('syncSetupContextChanged'));await flush();const result=await api('resolveSync',{workspaceId,preview:plan,strategy,choices});if(await acceptSyncResult(result))closeModal();}
  catch(failure){error.textContent=errorMessage(failure);error.hidden=false;}
  finally{state.busy=false;if(form.isConnected){form.querySelectorAll('button,input,select').forEach(el=>el.disabled=false);update();}render();}
 };
}
