 if(action==='propertyMenu'){
  if(!column)return;closeContextMenu();contextOrigin=el;const items=[['renameProperty','propertyRename','page'],['editProperty','editColumn','settings'],['propertyVisibility','propertyVisibility','eye'],['duplicateProperty','propertyDuplicate','copy'],['deleteColumn','removeColumn','trash'],['propertyLayout','propertyLayout','grid']];
  $('#context-root').innerHTML=`<div class="page-context-menu property-context-menu" role="menu" aria-label="${t('propertyMenu')}"><div class="context-title">${e(column.name)}</div>${items.map(([label,action,glyph])=>`<button type="button" role="menuitem" data-action="${action}" data-column="${e(id)}" class="${action==='removeColumn'?'danger':''}">${icon(glyph,17)}<span>${t(label)}</span></button>`).join('')}</div>`;
  const menu=$('.property-context-menu'),rect=menu.getBoundingClientRect(),origin=el.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(origin.left,innerWidth-rect.width-8))+'px';menu.style.top=Math.max(8,Math.min(origin.bottom,innerHeight-rect.height-8))+'px';menu.querySelector('button')?.focus();return;
 }
