 if(action==='propertyDuplicate'&&column){applyDatabaseChange(db=>{const copy=clone(db.columns.find(c=>c.id===id));copy.id=uid();const base=copy.name+' · '+t('copySuffix');copy.name=base;for(let i=2;db.columns.some(c=>c.name===copy.name);i++)copy.name=base+' '+i;db.columns.splice(db.columns.findIndex(c=>c.id===id)+1,0,copy);for(const row of db.rows)row.values[copy.id]=row.values[id]??'';if(Array.isArray(db.propertyLayout?.order)){const order=db.propertyLayout.order,position=order.indexOf(id);order.splice(position<0?order.length:position+1,0,copy.id);}});render();}
 if(action==='propertyVisibility'&&column){propertyPopover(t('propertyVisibility'),`<form id="property-visibility-form"><label class="form-field">${e(column.name)}<select name="visibility">${['always','nonempty','hidden'].map(mode=>`<option value="${mode}" ${(editor.database.propertyLayout?.visibility?.[id]||'always')===mode?'selected':''}>${t('property'+{always:'Always',nonempty:'Nonempty',hidden:'Hidden'}[mode])}</option>`).join('')}</select></label><div class="modal-footer"><button type="submit" class="button primary">${t('save')}</button></div></form>`,propertyAnchor(id),330);$('#property-visibility-form').onsubmit=event=>{event.preventDefault();setPropertyVisibility(id,new FormData(event.target).get('visibility'),target);closeModal();render();};}
