document.addEventListener('dragstart',event=>{const row=event.target.closest('[data-row-drag]');if(row&&!row.closest('.peek-background'))event.dataTransfer.setData('application/qingjian-row',row.dataset.rowDrag);});
document.addEventListener('dragover',event=>{if(event.target.closest('.board-column')&&!event.target.closest('.peek-background')&&!state.preview&&!state.page?.locked&&!state.busy)event.preventDefault();});
document.addEventListener('drop',event=>{if(state.page?.locked||state.preview||state.busy||event.target.closest('.peek-background'))return;const column=event.target.closest('.board-column');if(column&&state.page?.database){const id=event.dataTransfer.getData('application/qingjian-row'),row=state.page.database.rows.find(r=>r.id===id),property=state.page.database.columns.find(c=>c.id===state.dbGroup)||state.page.database.columns.find(c=>['select','status'].includes(c.type));if(row&&property){event.preventDefault();snapshot();row.values[property.id]=column.dataset.group;changed();render();}}});
window.addEventListener('beforeunload',event=>{if(state.dirty||recordDraft.dirty){event.preventDefault();event.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&(state.dirty||recordDraft.dirty))flush().catch(()=>{});});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.config?.preferences.theme==='system')applyPreferences();});
async function start(){try{if(native()){const info=await api('appInfo');desktopSupported=['macos','windows','linux'].includes(info.os);if(desktopSupported)await listenDesktopResume(releaseDesktopGuard);}state.config=await api('bootstrap');const params=new URL(location.href).searchParams,w=params.get('workspace'),id=params.get('page');if(w){if(!state.config.workspaces.some(x=>x.id===w))throw new Error(t('pageNotFound'));state.config.activeId=w;}applyPreferences();await refresh();render();if(id){if(!state.pages.some(p=>p.id===id&&!p.deleted))throw new Error(t('pageNotFound'));await navigate(id);}updateUI.start();autoSyncUI.start();if(desktopSupported)await desktopActions.start();}catch(error){$('#app').innerHTML=`<div class="fatal-error">${icon('info',36)}<h2>${t('operationFailed')}</h2><p>${e(errorMessage(error))}</p>${button(t('retry'),'reload','primary')}</div>`;$('[data-action="reload"]').onclick=()=>location.reload();if(desktopSupported)await desktopActions.start();}}
installMobileViewport();
start();
